const products=window.CIVILIZED_PRODUCTS;
let cart=JSON.parse(localStorage.getItem('civilized-men-cart')||'[]');
let wishlist=JSON.parse(localStorage.getItem('civilized-men-wishlist')||'[]');
let activeFilter='all',query='',sort='featured',selectedProduct=null,selectedSize=null;
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const grid=$('#products'),drawer=$('.drawer'),overlay=$('.overlay'),modal=$('.product-modal');
const money=n=>new Intl.NumberFormat('en-IN',{style:'currency',currency:'INR',maximumFractionDigits:0}).format(n);
const save=()=>{localStorage.setItem('civilized-men-cart',JSON.stringify(cart));localStorage.setItem('civilized-men-wishlist',JSON.stringify(wishlist))};
function visibleProducts(){let list=products.filter(p=>(activeFilter==='all'||p.cat===activeFilter)&&(`${p.name} ${p.sub}`.toLowerCase().includes(query)));if(sort==='low')list.sort((a,b)=>a.price-b.price);if(sort==='high')list.sort((a,b)=>b.price-a.price);return list}
function renderProducts(){const list=visibleProducts();$('.product-count').textContent=`${list.length} styles`;$('.empty-state').hidden=!!list.length;grid.innerHTML=list.map(p=>`<article class="product"><button class="wish ${wishlist.includes(p.id)?'saved':''}" data-wish="${p.id}" aria-label="Save ${p.name}">${wishlist.includes(p.id)?'♥':'♡'}</button><button class="product-media" data-view="${p.id}" aria-label="View ${p.name}"><img src="${p.image}" alt="${p.name}" loading="lazy">${p.fresh?'<span class="new">NEW</span>':''}</button><div class="product-info"><button class="product-title" data-view="${p.id}"><span class="product-name">${p.name}</span><span class="product-sub">${p.sub}</span></button><div class="price">${money(p.price)}</div></div><button class="quick" data-view="${p.id}">Choose size</button></article>`).join('')}
function renderCart(){const total=cart.reduce((s,x)=>s+x.price*x.qty,0),count=cart.reduce((s,x)=>s+x.qty,0);$('.badge').textContent=count;$('.cart-items').innerHTML=cart.length?cart.map((x,i)=>`<div class="cart-row"><img src="${x.image}" alt=""><div><b>${x.name}</b><span>Size ${x.size}</span><div class="qty"><button data-qty="${i}" data-delta="-1">−</button><b>${x.qty}</b><button data-qty="${i}" data-delta="1">+</button></div></div><div><b>${money(x.price*x.qty)}</b><button class="remove" data-remove="${i}">Remove</button></div></div>`).join(''):'<div class="empty-bag"><b>Your bag is empty</b><p>Explore the collection and add your favourites.</p></div>';const left=Math.max(0,1999-total);$('.delivery-progress').innerHTML=cart.length?(left?`Add <b>${money(left)}</b> more for free delivery.<progress max="1999" value="${total}"></progress>`:'<b>You unlocked free delivery.</b>'):'';$('.cart-total').innerHTML=cart.length?`<div><span>Subtotal</span><b>${money(total)}</b></div>`:'';$('.wish-count').textContent=wishlist.length;save()}
function openLayer(el){el.classList.add('open');overlay.classList.add('show');el.setAttribute('aria-hidden','false');document.body.classList.add('locked')}
function closeLayers(){drawer.classList.remove('open');modal.classList.remove('open');overlay.classList.remove('show');drawer.setAttribute('aria-hidden','true');modal.setAttribute('aria-hidden','true');document.body.classList.remove('locked')}
function viewProduct(id){selectedProduct=products.find(p=>p.id===+id);selectedSize=null;$('.modal-image img').src=selectedProduct.image;$('.modal-image img').alt=selectedProduct.name;$('#modal-title').textContent=selectedProduct.name;$('.modal-price').textContent=money(selectedProduct.price);$('.modal-description').textContent=selectedProduct.description;$('.sizes').innerHTML=selectedProduct.sizes.map(s=>`<button data-size="${s}">${s}</button>`).join('');$('.modal-add').textContent='Select a size';openLayer(modal)}
function addSelected(){if(!selectedSize){$('.modal-add').textContent='Please select a size';return}const found=cart.find(x=>x.id===selectedProduct.id&&x.size===selectedSize);if(found)found.qty++;else cart.push({...selectedProduct,size:selectedSize,qty:1});renderCart();closeLayers();openLayer(drawer);showToast('Added to your bag')}
function showToast(message){$('.toast').textContent=message;$('.toast').classList.add('show');setTimeout(()=>$('.toast').classList.remove('show'),1600)}
document.addEventListener('click',e=>{const t=e.target.closest('button');if(!t)return;if(t.dataset.view)viewProduct(t.dataset.view);if(t.dataset.wish){const id=+t.dataset.wish;wishlist=wishlist.includes(id)?wishlist.filter(x=>x!==id):[...wishlist,id];renderProducts();renderCart()}if(t.dataset.size){selectedSize=t.dataset.size;$$('.sizes button').forEach(x=>x.classList.toggle('selected',x.dataset.size===selectedSize));$('.modal-add').textContent=`Add to bag · ${money(selectedProduct.price)}`}if(t.dataset.remove!==undefined){cart.splice(+t.dataset.remove,1);renderCart()}if(t.dataset.qty!==undefined){const i=+t.dataset.qty;cart[i].qty+=+t.dataset.delta;if(cart[i].qty<1)cart.splice(i,1);renderCart()}if(t.matches('.filter')){$$('.filter').forEach(x=>x.classList.remove('active'));t.classList.add('active');activeFilter=t.dataset.filter;renderProducts()}});
$('#product-search').addEventListener('input',e=>{query=e.target.value.trim().toLowerCase();renderProducts()});
$('#sort').addEventListener('change',e=>{sort=e.target.value;renderProducts()});
$('.search-toggle').onclick=()=>{location.hash='shop';setTimeout(()=>$('#product-search').focus(),250)};$('.wishlist-toggle').onclick=()=>{location.hash='shop';showToast(wishlist.length?`${wishlist.length} saved style${wishlist.length>1?'s':''}`:'Your wishlist is empty')};$('.bag').onclick=()=>openLayer(drawer);$('.close').onclick=closeLayers;$('.modal-close').onclick=closeLayers;overlay.onclick=closeLayers;$('.modal-add').onclick=addSelected;$('.checkout').onclick=()=>alert('Checkout is ready to connect to Razorpay, Shopify or another payment provider.');
renderProducts();renderCart();if('serviceWorker'in navigator)navigator.serviceWorker.register('/sw.js');

